  var area=SystemParameters.WorkArea;Companion.Left=area.Right-90;Companion.Top=area.Bottom-160;try{if(File.Exists(layoutPath)){using var doc=JsonDocument.Parse(File.ReadAllText(layoutPath));var x=doc.RootElement.GetProperty("x").GetDouble();var y=doc.RootElement.GetProperty("y").GetDouble();if(doc.RootElement.TryGetProperty("coordinateFormat",out var format)&&format.GetString()=="physical")Win32.SetWindowPos(Win32.Handle(Companion),IntPtr.Zero,(int)x,(int)y,0,0,0x15);else{Companion.Left=x;Companion.Top=y;}if(doc.RootElement.TryGetProperty("width",out var width))Panel.Width=Math.Clamp(width.GetDouble(),320,800);if(doc.RootElement.TryGetProperty("height",out var height))Panel.Height=Math.Clamp(height.GetDouble(),420,1200);}}catch{/* A missing or obsolete layout does not affect reading records. */}ClampCompanion();Companion.SourceInitialized+=(_,_)=>Win32.Exclude(Companion);Panel.SourceInitialized+=(_,_)=>Win32.Exclude(Panel);Panel.SizeChanged+=(_,_)=>SaveLayout();Win32.Exclude(Companion);Win32.Exclude(Panel);glass=Win32.Backdrop(Panel);if(glass){Panel.Background=Brushes.Transparent;var target=HwndSource.FromHwnd(Win32.Handle(Panel)).CompositionTarget;if(target is not null)target.BackgroundColor=Colors.Transparent;Web.DefaultBackgroundColor=Drawing.Color.Transparent;}
