 IEnumerable<(string Title,string Command)> MenuItems(){yield return(Panel.IsVisible?"收起对话":"展开对话","toggle");yield return("框选读屏","capture");yield return("窗口读屏","capture-window");yield return("设置…","settings");yield return(Companion.IsVisible?"隐藏入口":"显示入口","companion");yield return("退出 Any Sidebar","quit");}
 internal void ShowPanel(){
  var anchor=Win32.Bounds(Win32.Handle(Companion));var area=Forms.Screen.FromHandle(Win32.Handle(Companion)).WorkingArea;var scale=Math.Max(96,Win32.GetDpiForWindow(Win32.Handle(Companion)))/96d;
  var width=Math.Min(area.Width,(int)Math.Round(Panel.Width*scale));var height=Math.Min(area.Height,(int)Math.Round(Panel.Height*scale));
  var x=anchor.Left-width-(int)(12*scale);if(x<area.Left)x=anchor.Right+(int)(12*scale);x=Math.Clamp(x,area.Left,Math.Max(area.Left,area.Right-width));var y=Math.Clamp(anchor.Bottom-height,area.Top,Math.Max(area.Top,area.Bottom-height));
