 internal void Reference(bool has){if(Companion.Content is Border b)b.BorderBrush=has?new SolidColorBrush(Color.FromRgb(38,125,220)):new SolidColorBrush(Color.FromRgb(184,216,249));}
 void ClampCompanion(){var handle=Win32.Handle(Companion);Win32.GetWindowRect(handle,out var rect);var area=Forms.Screen.FromHandle(handle).WorkingArea;var x=Math.Clamp(rect.Left,area.Left,Math.Max(area.Left,area.Right-rect.Width));var y=Math.Clamp(rect.Top,area.Top,Math.Max(area.Top,area.Bottom-rect.Height));Win32.SetWindowPos(handle,IntPtr.Zero,x,y,0,0,0x15);}
 void SaveLayout(){try{Directory.CreateDirectory(System.IO.Path.GetDirectoryName(layoutPath)!);var temporary=layoutPath+".tmp";Win32.GetWindowRect(Win32.Handle(Companion),out var rect);File.WriteAllText(temporary,JsonSerializer.Serialize(new{x=rect.Left,y=rect.Top,coordinateFormat="physical",width=Panel.Width,height=Panel.Height}));File.Move(temporary,layoutPath,true);}catch{/* Window placement is separate from conversation durability. */}}
